let app = await cua.getApp("Figma");
async function setField(desc, value) {
  const s = await app.getAXState({disableDiffing:true});
  const line = s.split("\n").find(l => l.includes(`Description: ${desc},`));
  if (!line) throw new Error(`Field not found: ${desc}`);
  const m = line.match(/\b(\d+) /);
  if (!m) throw new Error(`ID not found for: ${desc}`);
  await app.setValue(Number(m[1]), value);
  await new Promise(r=>setTimeout(r,400));
}
